// ============================================================================
// Sentinel AI — First Aid Emergency Guidance Service
// ============================================================================

import { AIFirstAidGuidance, SupportedIncidentType } from '../types';

export class FirstAidService {
  private static medicalDisclaimer =
    'DISCLAIMER: This guidance is generated by AI for immediate triage support only and does not substitute for professional medical care. CALL 911 / EMERGENCY SERVICES IMMEDIATELY.';

  private static triageProtocols: Record<AIFirstAidGuidance['category'], AIFirstAidGuidance> = {
    'Burn': {
      category: 'Burn',
      title: 'Thermal Burn & Heat Injury Triage Protocol',
      immediateSteps: [
        'Immediately remove subject from the heat or fire hazard area if safe to do so.',
        'Cool the burn with cool, running tap water for at least 20 minutes (do NOT use ice).',
        'Remove restrictive clothing or jewelry near the burn before swelling occurs.',
        'Cover the burn loosely with a sterile, non-adherent dressing or clean cling film.',
        'Monitor airway and breathing continuously while awaiting emergency medical responders.',
      ],
      contraindications: [
        'NEVER apply ice, ice water, butter, oil, toothpaste, or ointments to a severe burn.',
        'NEVER break blisters or peel away burned skin.',
        'NEVER remove clothing that is melted or stuck directly to the skin.',
      ],
      requiredEquipment: ['Cool running water / sterile saline', 'Sterile non-adherent burn dressings', 'Emergency thermal blanket'],
      medicalDisclaimer: FirstAidService.medicalDisclaimer,
    },

    'Fall': {
      category: 'Fall',
      title: 'Blunt Impact & Fall Trauma Protocol',
      immediateSteps: [
        'Do not move the fallen subject unless there is an immediate secondary hazard (fire, gas, structure collapse).',
        'Instruct the subject to remain still and avoid turning their neck or back.',
        'Check alertness, breathing, and pulse. If unresponsive and not breathing, initiate CPR immediately.',
        'If bleeding is present, apply gentle, direct pressure using a sterile gauze or clean cloth.',
        'Keep the subject warm and calm until EMS arrival.',
      ],
      contraindications: [
        'NEVER move a subject with suspected spinal, neck, or head injuries.',
        'NEVER give food, water, or oral medications to a trauma victim.',
        'NEVER straighten deformed limbs or joints.',
      ],
      requiredEquipment: ['Sterile trauma dressings', 'Neck immobility collar (by trained personnel)', 'Defibrillator (AED) on standby'],
      medicalDisclaimer: FirstAidService.medicalDisclaimer,
    },

    'Smoke Inhalation': {
      category: 'Smoke Inhalation',
      title: 'Toxic Smoke & Particulate Inhalation Protocol',
      immediateSteps: [
        'Move the subject immediately to fresh, unpolluted air upwind of the hazard.',
        'Loosen tight clothing around the neck, chest, and waist to facilitate breathing.',
        'If oxygen administration equipment is available and personnel are trained, administer high-flow supplemental oxygen.',
        'Place the subject in a comfortable sitting position (fowler position) if conscious.',
        'If subject becomes unresponsive, check pulse and commence cardiopulmonary resuscitation (CPR).',
      ],
      contraindications: [
        'NEVER allow the subject to re-enter the smoke-filled zone under any circumstances.',
        'NEVER leave an inhalation victim unmonitored; respiratory distress can rapidly escalate.',
      ],
      requiredEquipment: ['Emergency supplemental oxygen (BVM/Mask)', 'Pulse oximeter', 'First aid airway kit'],
      medicalDisclaimer: FirstAidService.medicalDisclaimer,
    },

    'Bleeding': {
      category: 'Bleeding',
      title: 'Hemorrhage & Acute Bleeding Control Protocol',
      immediateSteps: [
        'Apply firm, continuous direct pressure to the wound using a sterile gauze or clean pad.',
        'If bleeding soaks through the dressing, apply additional pads firmly over the top without removing original gauze.',
        'If injury is on a limb and bleeding is severe/arterial, apply a tourniquet 2-3 inches above the wound (never over a joint).',
        'Note the exact time the tourniquet was applied and inform EMS dispatch.',
        'Have the subject lie down and elevate their feet to prevent hypovolemic shock.',
      ],
      contraindications: [
        'NEVER remove a tourniquet once applied; only hospital trauma staff should release it.',
        'NEVER remove impaled objects from the body; pack dressings securely around the object.',
      ],
      requiredEquipment: ['Hemostatic gauze pads', 'Tactical arterial tourniquet', 'Trauma shears', 'Nitrile gloves'],
      medicalDisclaimer: FirstAidService.medicalDisclaimer,
    },

    'Electric Shock': {
      category: 'Electric Shock',
      title: 'High-Voltage Electrical Contact Triage Protocol',
      immediateSteps: [
        'ENSURE SCENE SAFETY FIRST: Do not touch the subject until electrical power source is verified shut off.',
        'If power cannot be shut off, use a dry, non-conductive object (wooden broom, fiberglass pole) to separate subject from contact.',
        'Check vital signs immediately; electrical shocks frequently cause cardiac arrest. Begin CPR and attach AED if pulse is absent.',
        'Inspect for both entry and exit thermal burn wounds once cardiac rhythm is stable.',
        'Cover electrical burns with dry sterile dressings.',
      ],
      contraindications: [
        'NEVER touch a victim still in contact with a live electrical circuit or pooled water near current.',
        'NEVER use metal objects or damp materials to assist the victim.',
      ],
      requiredEquipment: ['Automated External Defibrillator (AED)', 'Insulated rescue hook / dry wooden pole', 'CPR barrier mask'],
      medicalDisclaimer: FirstAidService.medicalDisclaimer,
    },

    'Choking': {
      category: 'Choking',
      title: 'Airway Obstruction & Choking Emergency Protocol',
      immediateSteps: [
        'Determine if subject can cough forcefully or speak. If they can cough, encourage them to clear airway naturally.',
        'If subject cannot breathe, cough, or speak, stand behind them and deliver 5 sharp back blows between shoulder blades.',
        'If obstruction remains, perform 5 abdominal thrusts (Heimlich maneuver) pulling inward and upward.',
        'Alternate 5 back blows and 5 abdominal thrusts until object is dislodged.',
        'If subject loses consciousness, lower carefully to the floor and begin chest compressions immediately.',
      ],
      contraindications: [
        'NEVER perform blind finger sweeps in the throat; this may push the obstruction deeper.',
        'NEVER perform abdominal thrusts on infants under 1 year old (use back slaps and chest thrusts instead).',
      ],
      requiredEquipment: ['Anti-choking suction device (LifeVac/Dechoker)', 'CPR barrier shield'],
      medicalDisclaimer: FirstAidService.medicalDisclaimer,
    },

    'Heat Stroke': {
      category: 'Heat Stroke',
      title: 'Hyperthermia & Heat Stroke Emergency Protocol',
      immediateSteps: [
        'Move the subject out of hot environment into an air-conditioned room or shaded area immediately.',
        'Strip away excess outer clothing and athletic gear.',
        'Initiate aggressive rapid cooling: apply cool damp sheets, ice packs to neck/armpits/groin, and mist with water while fanning.',
        'If subject is alert and swallowing normally, provide small sips of cool electrolyte water.',
        'Monitor body temperature continuously; cease aggressive cooling once core temperature drops to 101°F (38.3°C).',
      ],
      contraindications: [
        'NEVER give liquids to a subject who is lethargic, vomiting, or unconscious.',
        'NEVER give fever-reducing medications (aspirin/acetaminophen); they do not work for environmental heat stroke.',
      ],
      requiredEquipment: ['Instant cold packs', 'Misting spray bottles / high-velocity fan', 'Electrolyte replacement fluids'],
      medicalDisclaimer: FirstAidService.medicalDisclaimer,
    },

    'Gas Exposure': {
      category: 'Gas Exposure',
      title: 'Chemical Gas & Carbon Monoxide Triage Protocol',
      immediateSteps: [
        'Evacuate subject immediately to outdoor atmospheric fresh air.',
        'Ensure rescuers wear SCBA (Self-Contained Breathing Apparatus) before entering toxic gas vapor zones.',
        'If chemical vapor touched eyes or skin, flush with emergency eyewash/shower for 15 minutes.',
        'Administer 100% supplemental oxygen via non-rebreather mask at 15 L/min for suspected carbon monoxide poisoning.',
        'Keep subject quiet and rest physically to minimize oxygen metabolic demand.',
      ],
      contraindications: [
        'NEVER enter a confined space with active gas alarms without breathing apparatus.',
        'NEVER induce vomiting or administer neutralizing chemicals unless instructed by Poison Control.',
      ],
      requiredEquipment: ['100% Oxygen cylinder & non-rebreather mask', 'Emergency eyewash bottle', 'Multi-gas personal monitor'],
      medicalDisclaimer: FirstAidService.medicalDisclaimer,
    },

    'General': {
      category: 'General',
      title: 'Universal Emergency Medical Triage Protocol',
      immediateSteps: [
        'Assess the scene for safety before approaching.',
        'Check responsiveness and establish clear airway, breathing, and circulation (ABC).',
        'Call 911 / EMS immediately and provide exact facility coordinates and floor level.',
        'Keep subject comfortable, calm, and warm until professional medical arrival.',
      ],
      contraindications: [
        'NEVER move trauma victims unnecessarily.',
        'NEVER leave an unstable subject unattended.',
      ],
      requiredEquipment: ['Standard Industrial First Aid Kit', 'AED', 'Emergency Blanket'],
      medicalDisclaimer: FirstAidService.medicalDisclaimer,
    },
  };

  public static getFirstAidGuidance(
    categoryOrIncidentType: AIFirstAidGuidance['category'] | SupportedIncidentType
  ): AIFirstAidGuidance {
    // Map incident type to specific first aid protocol
    switch (categoryOrIncidentType) {
      case 'Fire':
      case 'Smoke':
      case 'Electrical Fire':
        return this.triageProtocols['Smoke Inhalation'];
      case 'Fall Detection':
      case 'Earthquake':
      case 'Industrial Accident':
        return this.triageProtocols['Fall'];
      case 'Gas Leak':
      case 'Chemical Leak':
        return this.triageProtocols['Gas Exposure'];
      case 'Short Circuit':
      case 'Power Failure':
        return this.triageProtocols['Electric Shock'];
      case 'Medical Emergency':
      case 'Person Unconscious':
      case 'Heart Attack (placeholder)':
        return this.triageProtocols['General'];
      case 'Violence':
      case 'Weapon Detection':
      case 'Intrusion':
        return this.triageProtocols['Bleeding'];
      case 'Burn':
      case 'Fall':
      case 'Smoke Inhalation':
      case 'Bleeding':
      case 'Electric Shock':
      case 'Choking':
      case 'Heat Stroke':
      case 'Gas Exposure':
      case 'General':
        return this.triageProtocols[categoryOrIncidentType];
      default:
        return this.triageProtocols['General'];
    }
  }

  public static getAllProtocols(): AIFirstAidGuidance[] {
    return Object.values(this.triageProtocols);
  }
}
